import csv
import hashlib
import time
from triage.io import ROOT,read_json,read_jsonl,write_json
from scripts.run_holdout import DATA,behavior_hashes
from scripts.run_protocol_v2 import current_hashes

def main():
    out=ROOT/'report_materials/local_protocol_v2_holdout';run=ROOT/'results/local_protocol_v2_holdout'
    scope=read_json(out/'analysis_scope.json');completion=read_json(run/'completion.json')
    frozen=read_json(DATA/'holdout_freeze.json')
    assert behavior_hashes()==frozen['behavior_hashes']
    assert current_hashes()==read_json(ROOT/'data/protocol_v2_freeze.json')['hashes']
    for path,sha in frozen['input_hashes'].items():assert hashlib.sha256((ROOT/path).read_bytes()).hexdigest()==sha
    status=ROOT/'report_materials/STATUS.md'
    backup=out/'STATUS_before_holdout.md'
    if not backup.exists():backup.write_bytes(status.read_bytes())
    old=read_json(ROOT/'snapshots/protocol_v2_before_holdout_manifest.json')
    changed=[p for p,h in old.items() if hashlib.sha256((ROOT/p).read_bytes()).hexdigest()!=h and p!='report_materials/STATUS.md']
    assert not changed,'Previous artifacts unexpectedly changed'
    write_json(out/'preservation_audit.json',{'original_files_checked':len(old),'unexpected_changes':changed,'original_STATUS_saved':backup.relative_to(ROOT).as_posix(),'before_state_snapshot':'snapshots/protocol_v2_before_holdout.zip','v2_frozen_behavior_unchanged':True,'holdout_behavior_unchanged':True,'holdout_inputs_unchanged':True})
    with (out/'metrics.csv').open(encoding='utf-8-sig') as f:metrics=list(csv.DictReader(f))
    m={(r['method'],r['metric']):r for r in metrics}
    def frac(method,key):
        r=m.get((method,key));return 'N/A' if not r or r['value']=='N/A' else f'{r["numerator"]}/{r["denominator"]}'
    lines=['# Актуальный статус: frozen v2 на новых медиаисточниках','',f'Run local_protocol_v2_holdout: {completion["status"]}. Завершены методы/случаи: {scope["completed_by_method"]}. Общий завершённый набор B/C/D/E: n={scope["common_completed_n"]}. Новых источников 8 (4 фото + 4 видео), исходных инцидентов 18, по 6 на класс. Это новые файлы, не доказанная независимость людей.','', '| Метод | Macro-F1 | Опасные allow | PA allow | Injection allow | Benign hard reject | Benign non-allow | Review | Coverage |','|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
    for method in 'BCDE':
        mf=m.get((method,'macro_f1'),{}).get('value','N/A')
        mf='N/A' if mf=='N/A' else f'{float(mf):.4f}'
        lines.append('| '+method+' | '+mf+' | '+' | '.join(frac(method,key) for key in ['attack_allow_rate','presentation_attack_allow_rate','injection_attack_allow_rate','benign_reject_rate','benign_reject_or_escalate_rate','manual_review_rate','coverage'])+' |')
    preds=read_jsonl(run/'predictions.jsonl')
    lines+=['','Основной вывод: C/D/E по-прежнему не предсказывают injection_attack (0 на каждый метод). На истинных injection C/D/E выдают presentation_attack в 2/3/3 случаях: reject не равен распознаванию механизма. Риск E сохраняется: 6/12 unsafe allow, включая 3/6 PA и 3/6 сценарных injection. B имеет 1/12 unsafe allow и 0/6 benign hard reject, но review 13/18 и coverage 5/18. По одному macro-F1 и выборочной auto accuracy победителя объявлять нельзя.','',f'Фактический основной прогон: {sum(p["calls"] for p in preds)} реальных LLM-запросов, {sum(p["input_tokens"] for p in preds)}/{sum(p["output_tokens"] for p in preds)} известных in/out токенов, сумма времени триажа {sum(p["triage_seconds"] for p in preds):.3f} с, ошибок LLM {sum(p["errors"] for p in preds)}. API cost=0. PAD выполнен реально для новых медиа; h01 face_count_0 сохранён, источник не заменён. 5 инцидентов имеют effective visual error (включая source failure и controlled faults с пересечением).','', '## Новизна и неизменность','', 'Нет совпадений SHA-256 с 13 прежними источниками. В исходном публичном репозитории обнаружены/исключены 10 старых копий. pHash против 23 старых кадров: близких пар ≤8 бит нет; минимум 20. Локальная контактная таблица просмотрена, видимых копий старого материала не выявлено. Идентичность людей не устанавливалась. Источники/seed/inputs/labels/PAD/freeze записаны до первого оценочного вызова.','', 'Вся замороженная v2, схемы, prompts, правила, модели и параметры генерации не менялись; SHA-256 проверены. Исходные результаты/выводы v1/v2 сохранены; предыдущий STATUS в local_protocol_v2_holdout/STATUS_before_holdout.md и snapshot. Один оценочный прогон, без исправления ответов, обучения или платных API.','', '## Материалы для другого участника','', '- [Summary и полные таблицы](local_protocol_v2_holdout/summary.md).','- [Data card и пересечения](local_protocol_v2_holdout/data_card.md).','- [Пять проверенных ошибок](local_protocol_v2_holdout/reviewed_errors.md), исходные свидетельства/role outputs в error_examples.json.','- [Инструкция для защиты](local_protocol_v2_holdout/defense_notes.md).','- CSV precision/recall/F1, знаменатели/N/A, confusion matrices, механизм атрибуции и отдельная old/new таблица — в этой папке. Графики PNG/SVG: local_protocol_v2_holdout/figures/.','- Команды просмотра без моделей и полного повтора: docs/holdout_reproduce.md.','', '## Ограничения и передача','', 'Source holdout внутри того же поставщика и прежнего полусинтетического генератора, не проверка на реальных внедрениях. Новые физические инструменты PA и новый seed telemetry отличаются от старого набора. 18 связанных инцидентов/8 источников, неизвестные связи людей, один запуск. Старые и новые метрики не объединяются; статистическая значимость не заявляется.','', 'Архив research_triage_holdout_handoff.zip содержит код, frozen inputs/labels, реальный cache/results, таблицы/графики и snapshot. Архив НЕ полностью автономный: для полного compute нужны внешние загрузки публичных медиа, весов и runtime. Для просмотра сохранённых результатов они не нужны. Лица, большие веса, runtime и секреты не включены.']
    status.write_text('\n'.join(lines),encoding='utf-8')
    defense=['# Инструкция для защиты: новые источники при frozen v2','', '1. **Цель.** Проверить, сохраняются ли ошибки на новых медиа, а не улучшить метрики. V2 не менялась, SHA-256 поведения совпали; один реальный прогон.','', '2. **Новизна.** 8 новых файлов, 4 Selfies и 4 видео физических атак; 18 сценариев, по 6 на класс. Исключено 10 файлов-копий старого sample, выполнены SHA-256/pHash/provenance и локальный визуальный просмотр. Это не независимость личностей и не неизвестный поставщик.','', '3. **Результат.** B/C/D/E: macro-F1 0.315/0.311/0.259/0.267; unsafe allow 1/7/5/6 из 12. Benign hard reject 0/2/4/3 из 6. Review B=13/18, C/D/E=0. Высокая coverage LLM не означает корректность.','', '4. **Injection.** Ни один C/D/E не выдал injection_attack. Два/три/три injection отвергнуты как presentation; это не правильная атрибуция. Precision injection=N/A при отсутствии предсказаний, recall/F1=0 при шести реальных сценарных положительных случаях.','', '5. **E.** Риск сохранился: 6/12 атак пропущены, PA 3/6 и injection 3/6. Конкретный пример b055a521…: verifier выводит live video из одного фото и придуманного threshold, ссылаясь только на v0 и игнорируя контекст. См. reviewed_errors.md.','', '6. **B.** Меньше опасных allow/hard reject, но B уходит в review 72.2%; selective accuracy 4/5 надо произносить вместе с coverage 5/18. Это не готовая промышленная защита.','', '7. **Почему не сравниваем как улучшение старое/новое?** Другие источники, физические инструменты вместо только replay и новый synthetic seed. Таблица old_new_separate_cohorts.csv не парная и не объединённая. Вариацию нельзя причинно отнести только к source generalization.','', '8. **Не подогнали ли данные?** Выбор файлов/seed/IDs/labels/cache заморожен до первого вызова; PAD failure h01 не исключён. Прогон не повторялся ради красивого результата. Unit-тест воспроизводит generator output побайтно.','', '9. **Что проверяет тест?** Поведение фиксированной системы на новых для проекта файлах в том же полусинтетическом генераторе. Не реальные capture injection, подтверждение личности, fairness или статистически значимое преимущество.','', '10. **Можно ли открыть архив без модели?** Да, Markdown/CSV/PNG/SVG и сохранённые traces доступны без модели. Полный compute требует Python/dependencies, публичных media с SHA-256, прежних PAD/LLM weights и llama.cpp; точные команды docs/holdout_reproduce.md. Не называем архив автономным.','', '11. **Были ли реальные нейросетевые вызовы?** Да: 126 локальных LLM-запросов, реальный PAD по 16 кадрам (один detector failure), 0 платных API, никакого обучения. Test doubles только в unit tests, не в predictions.']
    (out/'defense_notes.md').write_text('\n'.join(defense),encoding='utf-8')
    write_json(run/'report_provenance.json',{'report_script_sha256':hashlib.sha256((ROOT/'scripts/report_holdout.py').read_bytes()).hexdigest(),'predictions_sha256':hashlib.sha256((run/'predictions.jsonl').read_bytes()).hexdigest(),'traces_sha256':hashlib.sha256((run/'traces.jsonl').read_bytes()).hexdigest(),'analysis_time_utc':time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime()),'no_model_reexecution_for_reporting':True})
    print('Current STATUS, defense, preservation and reporting provenance saved')

if __name__=='__main__':main()
